// Minimal Canvas Dodge game
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  // Set canvas size to its displayed size
  canvas.width = canvas.clientWidth;
  canvas.height = canvas.clientHeight;

  const player = {
    w: 30,
    h: 30,
    x: canvas.width / 2 - 15,
    y: canvas.height - 40,
    speed: 5,
    color: '#0af',
    move(dx) {
      this.x = Math.max(0, Math.min(canvas.width - this.w, this.x + dx));
    }
  };

  const circles = [];
  let lastSpawn = 0;
  const spawnInterval = 1000; // ms
  let gameOver = false;
  let score = 0;

  function spawnCircle() {
    const radius = 15 + Math.random() * 10;
    circles.push({
      x: Math.random() * (canvas.width - 2 * radius) + radius,
      y: -radius,
      r: radius,
      speed: 2 + Math.random() * 2,
    });
  }

  function update(dt) {
    if (gameOver) return;
    // spawn
    if (performance.now() - lastSpawn > spawnInterval) {
      spawnCircle();
      lastSpawn = performance.now();
    }
    // move circles
    for (let i = circles.length - 1; i >= 0; i--) {
      const c = circles[i];
      c.y += c.speed;
      if (c.y - c.r > canvas.height) {
        circles.splice(i, 1);
        score++;
      } else if (rectCircleCollide(player, c)) {
        gameOver = true;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // circles
    ctx.fillStyle = '#f55';
    for (const c of circles) {
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // score / game over text
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop(timestamp) {
    const dt = timestamp - (loop.last || timestamp);
    loop.last = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Input handling
  document.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') player.move(-player.speed);
    else if (e.key === 'ArrowRight') player.move(player.speed);
  });
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    player.x = Math.max(0, Math.min(canvas.width - player.w, mx - player.w / 2));
  });

  function rectCircleCollide(rect, circle) {
    const distX = Math.abs(circle.x - (rect.x + rect.w / 2));
    const distY = Math.abs(circle.y - (rect.y + rect.h / 2));
    if (distX > rect.w / 2 + circle.r) return false;
    if (distY > rect.h / 2 + circle.r) return false;
    if (distX <= rect.w / 2) return true;
    if (distY <= rect.h / 2) return true;
    const dx = distX - rect.w / 2;
    const dy = distY - rect.h / 2;
    return dx * dx + dy * dy <= circle.r * circle.r;
  }

  requestAnimationFrame(loop);
})();
